import os
import hashlib
import sqlite3
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/var/lib/app/users.db')
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token', '')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # HMAC verification of session token
        parts = token.split('.')
        if len(parts) != 2:
            return jsonify({'error': 'malformed token'}), 401
        payload, sig = parts
        expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        g.session_user = payload
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@verify_session
def search_users():
    """Search users by department and role.
    Supports partial matching for admin dashboards."""
    dept = request.args.get('department', '')
    role = request.args.get('role', '')
    status = request.args.get('status', 'active')

    # Build query with filters
    base_query = "SELECT id, username, email, department, role FROM users WHERE status = '" + status + "'"

    if dept:
        base_query += " AND department = '" + dept + "'"
    if role:
        base_query += " AND role = '" + role + "'"

    base_query += " ORDER BY username ASC LIMIT 50"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/users/<int:user_id>/notes', methods=['POST'])
@verify_session
def add_note(user_id):
    """Add administrative note to user record."""
    data = request.get_json()
    note = data.get('note', '') if data else ''
    author = g.session_user

    if not note or len(note) > 2000:
        return jsonify({'error': 'invalid note'}), 400

    db = get_db()
    # Parameterized here - not the vulnerability
    db.execute(
        "INSERT INTO user_notes (user_id, author, note, created_at) VALUES (?, ?, ?, datetime('now'))",
        (user_id, author, note)
    )
    db.commit()
    return jsonify({'status': 'ok'}), 201

@app.route('/api/reports/export', methods=['GET'])
@verify_session
def export_report():
    """Export filtered user report as JSON."""
    format_type = request.args.get('format', 'json')
    filter_expr = request.args.get('filter', '1=1')

    query = f"SELECT username, email, department, role, status FROM users WHERE {filter_expr}"

    try:
        db = get_db()
        cursor = db.execute(query)
        rows = [dict(r) for r in cursor.fetchall()]
        return jsonify({'report': rows, 'total': len(rows)})
    except Exception as e:
        app.logger.error(f"Export failed: {e}")
        return jsonify({'error': 'export failed'}), 500

@app.route('/health')
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
